import csv
import json
import sys
import os
import datetime

def parse_date(date_str):
    date_str = date_str.strip()
    if not date_str:
        return None

    # Handle Excel serial dates
    if date_str.isdigit():
        # Excel epoch is 1899-12-30 for dates after 1900-02-28
        dt = datetime.datetime(1899, 12, 30) + datetime.timedelta(days=int(date_str))
        return dt.strftime('%Y-%m-%d')

    # Handle common date formats
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%m-%d-%Y'):
        try:
            dt = datetime.datetime.strptime(date_str, fmt)
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            pass

    return date_str

def format_amount(amount_str):
    amount_str = amount_str.strip()
    if not amount_str:
        return None

    # Remove currency symbols and commas
    amount_str = amount_str.replace(',', '').replace('$', '')
    if not amount_str:
        return None

    try:
        float(amount_str)
        return amount_str
    except ValueError:
        return amount_str

def main():
    if len(sys.argv) < 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load LCA Disclosure data
    lca_data = {}
    lca_file = os.path.join(packet_dir, 'lca_disclosure.csv')
    if os.path.exists(lca_file):
        with open(lca_file, 'r', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_number = row.get('CASE_NUMBER', '').strip()
                if not case_number:
                    continue
                if case_number not in lca_data:
                    lca_data[case_number] = []
                lca_data[case_number].append(row)

    results = {}

    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::', 1)
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            col = None
            doc = "lca_disclosure"
            is_date = False
            is_amount = False

            if fact == "offered wage":
                col = "WAGE_RATE_OF_PAY_FROM"
                is_amount = True
            elif fact == "prevailing wage":
                col = "PREVAILING_WAGE"
                is_amount = True
            elif fact == "begin date":
                col = "BEGIN_DATE"
                is_date = True
            elif fact == "end date":
                col = "END_DATE"
                is_date = True
            else:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            records = lca_data.get(entity, [])

            for rec in records:
                val = rec.get(col, '')
                if val is not None:
                    val = val.strip()
                if val:
                    if is_date:
                        val = parse_date(val)
                    elif is_amount:
                        val = format_amount(val)

                    if val is not None:
                        values.add(val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], doc]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

