import csv
import json
import sys
import os
import datetime

def clean_amount(val):
    if not val:
        return ""
    return val.replace('$', '').replace(',', '').strip()

def clean_date(date_str):
    if not date_str:
        return ""
    date_str = date_str.strip()

    # Try parsing as Excel serial date
    try:
        excel_date = int(date_str)
        # Excel's epoch is 1900-01-01, but it incorrectly considers 1900 a leap year.
        # For dates after 1900-02-28, the epoch effectively becomes 1899-12-30.
        return (datetime.date(1899, 12, 30) + datetime.timedelta(days=excel_date)).strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try parsing common date formats
    for fmt in ("%m/%d/%Y", "%Y-%m-%d", "%m/%d/%y", "%m-%d-%Y", "%Y/%m/%d"):
        try:
            return datetime.datetime.strptime(date_str, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass

    return date_str

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    lca_path = os.path.join(packet_dir, 'lca_disclosure.csv')

    data = {}
    if os.path.exists(lca_path):
        with open(lca_path, 'r', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_number = row.get('CASE_NUMBER')
                if not case_number:
                    continue
                if case_number not in data:
                    data[case_number] = []
                data[case_number].append(row)

    results = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            values = set()
            docs = set()

            if entity in data:
                for row in data[entity]:
                    val = ""
                    if fact == 'offered wage':
                        val = clean_amount(row.get('WAGE_RATE_OF_PAY_FROM'))
                    elif fact == 'prevailing wage':
                        val = clean_amount(row.get('PREVAILING_WAGE'))
                    elif fact == 'begin date':
                        val = clean_date(row.get('BEGIN_DATE'))
                    elif fact == 'end date':
                        val = clean_date(row.get('END_DATE'))

                    if val:
                        values.add(val)
                        docs.add('lca_disclosure')

            if not values:
                pair_result[fact] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact] = "CONFLICT"
            else:
                pair_result[fact] = [list(values)[0], list(docs)[0]]

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

